        processes.Bounds=new(24,348,732,186);processes.Font=BarcaUi.Font(10);var rowSize=new ImageList{ImageSize=new(1,32)};processes.SmallImageList=rowSize;processes.Disposed+=(_,_)=>rowSize.Dispose();processes.BackColor=BarcaUi.Surface;processes.ForeColor=BarcaUi.Text;processes.Columns.Add("进程",345);processes.Columns.Add("PID",85);processes.Columns.Add("CPU ↓",115);processes.Columns.Add("内存",187);processes.ClientSizeChanged+=(_,_)=>{if(processes.Columns.Count==4)processes.Columns[3].Width=Math.Max(100,processes.ClientSize.Width-545);};processes.ColumnClick+=(_,e)=>{if(e.Column is 2 or 3){sortCpu=e.Column==2;processes.Columns[2].Text=sortCpu?"CPU ↓":"CPU";processes.Columns[3].Text=sortCpu?"内存":"内存 ↓";Render();}};processes.DrawColumnHeader+=(_,e)=>{using var brush=new SolidBrush(BarcaUi.Raised);e.Graphics.FillRectangle(brush,e.Bounds);TextRenderer.DrawText(e.Graphics,e.Header?.Text??"",Font,e.Bounds,BarcaUi.Muted,TextFormatFlags.VerticalCenter);};processes.DrawItem+=(_,_)=>{};processes.DrawSubItem+=(_,e)=>{using var brush=new SolidBrush(e.Item!.Selected?BarcaUi.Raised:e.ItemIndex%2==0?BarcaUi.Surface:BarcaUi.Canvas);e.Graphics.FillRectangle(brush,e.Bounds);TextRenderer.DrawText(e.Graphics,e.SubItem?.Text??"",Font,Rectangle.Inflate(e.Bounds,-9,0),e.ColumnIndex==2?BarcaUi.Gold:BarcaUi.Text,TextFormatFlags.VerticalCenter|TextFormatFlags.EndEllipsis);};Controls.Add(processes);
