    }
    void Render(){if(IsDisposed||!Visible||monitor.Current is not{} s)return;cpuTrack.Fraction=s.Cpu/100;memoryTrack.Fraction=s.TotalMemory>0&&s.AvailableMemory is{} available?1-(double)available/s.TotalMemory.Value:null;cpu.Text=s.Cpu is{} c?$"{c:0.0}%":"采样中 / 暂不可读";memory.Text=s.TotalMemory is{} total&&s.AvailableMemory is{} free?$"{Bytes(total-free)} / {Bytes(total)}":"暂不可读取";network.Text=$"↓ {Bytes(s.Download)}/s   ↑ {Bytes(s.Upload)}/s";disk.Text=Bytes(s.DiskFree);processes.BeginUpdate();processes.Items.Clear();foreach(var p in s.Processes.OrderByDescending(p=>sortCpu?(p.Cpu??0):(double)(p.Memory??0)).ThenByDescending(p=>p.Memory??0).Take(12)){var item=new ListViewItem([p.Name,p.Id.ToString(),p.Cpu is{} load?$"{load:0.0}%":"—",Bytes(p.Memory)]);processes.Items.Add(item);}processes.EndUpdate();processes.Invalidate();stamp.Text=$"更新于 {s.Time.LocalDateTime:HH:mm:ss} · 进程约4秒刷新 · 网速为网卡合计（含虚拟网卡）\n"+s.Note;}
    protected override void Dispose(bool disposing){if(disposing){monitor.Updated-=Render;theme.Dispose();}base.Dispose(disposing);}
