sealed class ResourceTrack:Control
{
    double? fraction;
    [System.ComponentModel.DesignerSerializationVisibility(System.ComponentModel.DesignerSerializationVisibility.Hidden)]
    public double? Fraction{get=>fraction;set{fraction=value;Invalidate();}}
    public ResourceTrack(){SetStyle(ControlStyles.UserPaint|ControlStyles.AllPaintingInWmPaint|ControlStyles.OptimizedDoubleBuffer,true);}
    protected override void OnPaint(PaintEventArgs e){e.Graphics.Clear(BarcaUi.Line);if(fraction is{} value){using var brush=new SolidBrush(value>=.9?Appearance.Red:BarcaUi.Gold);e.Graphics.FillRectangle(brush,0,0,(float)(Width*Math.Clamp(value,0,1)),Height);}}
}
